        Test.startTest();
        insert opp;
        Test.stopTest();

        opp = [SELECT Id, NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(OpportunityWonHandler.HANDOVER, opp.NextStep,
            'NextStep should be set to handover for newly won opportunity');

