        // Attach finalizer before any work so it runs whether the job succeeds or fails
        System.attachFinalizer(new ErpSyncFinalizer(this.accountIds, this.attempt));

        // Fetch the accounts to be synced
        List<Account> accts = [
            SELECT Id, Description
            FROM Account
            WHERE Id IN :accountIds
        ];

        // Mark each account as synced
        for (Account a : accts) {
            a.Description = 'Synced to ERP';
        }

        // All‑or‑nothing DML – any exception will propagate and roll back the transaction
        update accts;
    }
}
