public class OpportunityPipelineHandler {
    public static void handle(
        boolean isInsert,
        boolean isUpdate,
        boolean isDelete,
        boolean isUndelete,
        List<Opportunity> newOpps,
        List<Opportunity> oldOpps,
        Map<Id, Opportunity> newMap,
        Map<Id, Opportunity> oldMap
    ) {
        Set<Id> accountIds = new Set<Id>();

        if (isInsert) {
            for (Opportunity o : newOpps) {
                if (!o.IsClosed) {
                    accountIds.add(o.AccountId);
                }
            }
        } else if (isDelete) {
            for (Opportunity o : oldOpps) {
                if (!o.IsClosed) {
                    accountIds.add(o.AccountId);
                }
            }
        } else if (isUndelete) {
            for (Opportunity o : newOpps) {
                if (!o.IsClosed) {
                    accountIds.add(o.AccountId);
                }
            }
        } else if (isUpdate) {
            for (Opportunity o : newOpps) {
                Opportunity old = oldMap.get(o.Id);
                boolean wasOpen = !old.IsClosed;
                boolean nowOpen = !o.IsClosed;
                boolean accountChanged = (old.AccountId != o.AccountId);
                boolean amountChanged = (old.Amount != o.Amount);
                if (wasOpen != nowOpen || accountChanged) {
                    if (wasOpen) {
                        accountIds.add(old.AccountId);
                    }
                    if (nowOpen) {
                        accountIds.add(o.AccountId);
                    }
                } else if (wasOpen && nowOpen && amountChanged) {
                    accountIds.add(o.AccountId);
                }
            }
        }

        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> pipelineMap = new Map<Id, Decimal>();
        Map<Id, Integer> countMap = new Map<Id, Integer>();

        for (AggregateResult ar : [
            SELECT AccountId accId, SUM(Amount) sumAmt, COUNT() cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Decimal sumAmt = (Decimal) ar.get('sumAmt');
            Integer cnt = (Integer) ar.get('cnt');
            pipelineMap.put(accId, sumAmt == null ? 0 : sumAmt);
            countMap.put(accId, cnt);
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Decimal sum = pipelineMap.containsKey(accId) ? pipelineMap.get(accId) : 0;
            Integer cnt = countMap.containsKey(accId) ? countMap.get(accId) : 0;
            Account a = new Account(Id = accId);
            a.FB_Open_Pipeline__c = sum;
            a.FB_Open_Opportunities__c = cnt;
            accountsToUpdate.add(a);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
