public class Accounts extends fflib_SObjects implements IAccounts {
    public Accounts(List<Account> records) {
        super(records);
    }

    public static IAccounts newInstance(List<Account> records) {
        return (IAccounts) Application.Domain.newInstance(records);
    }

    public static IAccounts newInstance(Set<Id> accountIds) {
        List<Account> records = (List<Account>) Application.Selector.newInstance().selectById(accountIds);
        return newInstance(records);
    }

    public override Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public override Object getType() {
        return Account.class;
    }

    public class Constructor implements fflib_SObjectDomain.ISObjectConstructor {
        public fflib_SObjectDomain newInstance(List<SObject> records) {
            return new Accounts((List<Account>) records);
        }
    }

    public List<Account> getAccounts() {
        return (List<Account>) records;
    }

    public IAccounts selectByRating(String rating) {
        List<Account> filtered = new List<Account>();
        for (Account a : (List<Account>) records) {
            if (rating == null ? a.Rating == null : rating.equals(a.Rating)) {
                filtered.add(a);
            }
        }
        return (IAccounts) Application.Domain.newInstance(filtered);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account a : (List<Account>) records) {
            if (a.OwnerId != null) {
                ownerIds.add(a.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (Account a : (List<Account>) records) {
            a.Rating = rating;
        }
    }
}
