        // old records (pre‑update)
        Contact old1 = new Contact(FirstName='Old1', LastName='L1', Email='old1@example.com', HasOptedOutOfEmail=true);
        Contact old2 = new Contact(FirstName='Old2', LastName='L2', Email='old2@example.com', HasOptedOutOfEmail=false);
