public class CaseEscalationService {
    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        // 1. Validate reason
        if (String.isBlank(reason)) {
            throw new EscalationException('Reason cannot be blank');
        }

        // 2. Early exit for null/empty caseIds
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // 3. Obtain selector via Application.Selector factory
        ICasesSelector selector = CasesSelector.newInstance();
        List<Case> cases = selector.selectById(caseIds);

        List<Case> casesToUpdate = new List<Case>();
        List<Task> tasksToInsert = new List<Task>();

        for (Case c : cases) {
            // Skip Closed or already escalated cases
            if (c.Status == 'Closed' || c.IsEscalated) {
                continue;
            }

            // Mark case for escalation
            c.IsEscalated = true;
            c.Priority = 'High';
            casesToUpdate.add(c);

            // Create follow‑up task
            Task t = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = Date.today().addDays(1),
                Priority = 'High'
            );
            tasksToInsert.add(t);
        }

        // 4. If nothing to do, exit without committing
        if (casesToUpdate.isEmpty() && tasksToInsert.isEmpty()) {
            return;
        }

        // 5. Perform DML via a single UnitOfWork
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        for (Case cToUpdate : casesToUpdate) {
            uow.registerDirty(cToUpdate);
        }
        for (Task tNew : tasksToInsert) {
            uow.registerNew(tNew);
        }

        uow.commitWork();
    }
}
