public with sharing class AccountOnboardingService {
    /**
     * Creates Accounts and related Contacts using a single Unit of Work.
     *
     * @param contactLastNamesByAccountName Map where key is the Account Name and value is a list of Contact Last Names.
     * @return List of newly inserted Accounts with Ids populated.
     */
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName
    ) {
        // Return early for null or empty input – no DML executed.
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        // List that will be returned (same instances passed to the UoW).
        List<Account> accountsToReturn = new List<Account>();

        // Unit of Work for Account and Contact.
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new Schema.SObjectType[] { Account.SObjectType, Contact.SObjectType }
        );

        // Iterate over each account name.
        for (String accName : contactLastNamesByAccountName.keySet()) {
            List<String> lastNames = contactLastNamesByAccountName.get(accName);

            // Guard against null last‑name list.
            if (lastNames == null) {
                continue;
            }

            // Create the Account.
            Account acc = new Account(Name = accName);
            accountsToReturn.add(acc);
            uow.registerNew(acc);

            // Create Contacts and relate them to the Account.
            for (String ln : lastNames) {
                // Skip blank last names.
                if (String.isBlank(ln)) {
                    continue;
                }
                Contact con = new Contact(LastName = ln);
                uow.registerNew(con);
                // Register the relationship: Contact.AccountId → Account.
                uow.registerRelationship(con, Contact.AccountId, acc);
            }
        }

        // Commit all pending work in a single transaction.
        uow.commitWork();

        // Accounts now have their Ids populated.
        return accountsToReturn;
    }
}
