public with sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load opportunities via the selector
        List<Opportunity> opps = OpportunitiesSelector.newInstance().selectById(opportunityIds);
        // Filter out any that are already Closed Won
        List<Opportunity> toUpdate = new List<Opportunity>();
        for (Opportunity o : opps) {
            if (o.StageName != 'Closed Won') {
                toUpdate.add(o);
            }
        }

        if (toUpdate.isEmpty()) {
            return 0;
        }

        // Obtain a unit of work from the factory (use the interface type)
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        // Prepare opportunity updates and register them
        for (Opportunity o : toUpdate) {
            o.StageName = 'Closed Won';
            o.CloseDate = Date.today();
            uow.registerUpdated(o);
        }

        // Prepare platform events and register them for publishing after commit
        for (Opportunity o : toUpdate) {
            Deal_Won__e ev = new Deal_Won__e();
            ev.Opportunity_Id__c = o.Id;
            ev.Amount__c = o.Amount;
            uow.registerEvent(ev);
        }

        // Commit updates and publish events (events published after successful commit)
        uow.commitWork();

        return toUpdate.size();
    }
