/**
 * Queueable that sends each newly created Account to the ERP as an
 * individual customer record. The ERP expects a JSON array with a single
 * object per callout:
 *   [{"salesforceId":"001...","name":"Acme GmbH","country":"Germany"}]
 *
 * The Queueable processes Accounts in batches of 100 to stay within the
 * 100 callout limit per transaction, chaining additional batches when
 * more than 100 Accounts are supplied.
 */
public class ErpCustomerSyncQueueable implements Queueable, Database.AllowsCallouts {
    private List<Id> idsToProcess;

    public ErpCustomerSyncQueueable(List<Id> ids) {
        this.idsToProcess = ids;
    }

    public void execute(QueueableContext context) {
        // Retrieve the Accounts we need to send to ERP.
        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :idsToProcess
        ];

        if (accounts.isEmpty()) {
            return;
        }

        // Constants
        private final Integer BATCH_LIMIT = 100;
        Integer batchSize = accounts.size() > BATCH_LIMIT ? BATCH_LIMIT : accounts.size();

        // Build the list of maps for the current batch.
        List<Map<String, Object>> payloads = new List<Map<String, Object>>();
        for (Integer i = 0; i < batchSize; i++) {
            Account acc = accounts[i];
            Map<String, Object> m = new Map<String, Object>();
            m.put('salesforceId', acc.Id);
            m.put('name', acc.Name);
            m.put('country', acc.BillingCountry == null ? null : acc.BillingCountry);
            payloads.add(m);
        }

        // Serialize to JSON array.
        String jsonBody = JSON.serialize(payloads);

        // Make the callout via the Named Credential.
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(jsonBody);

        Http http = new Http();
        try {
            HttpResponse res = http.send(req);
            // Per the ticket, we ignore the response (ERP returns 202 Accepted).
            // Any exception will propagate and be logged in the Apex job logs.
        } catch (Exception e) {
            System.debug(
                LoggingLevel.ERROR,
                'ErpCustomerSyncQueueable: Failed to send Account Id '
                + accounts[0].Id + ' to ERP. Error: ' + e.getMessage()
            );
        }

        // If there are more accounts left, chain another Queueable job.
        if (accounts.size() > batchSize) {
            List<Id> remainingIds = new List<Id>();
            for (Integer i = batchSize; i < accounts.size(); i++) {
                remainingIds.add(accounts[i].Id);
            }
            System.enqueueJob(new ErpCustomerSyncQueueable(remainingIds));
        }
    }
}
