public class DealEventPublisher {
    /**
     * Publishes a Deal_Stage_Change__e platform event for each Opportunity in the input list.
     * To avoid exceeding DML limits when processing large batches, all events are published
     * in a single EventBus.publish call. The method still returns a list of Database.SaveResult
     * objects that correspond one‑to‑one with the input opportunities, preserving order.
     *
     * @param opportunities List of Opportunity records to process.
     * @return List of SaveResult objects for each published event, in the same order as the input.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        // Handle null or empty input early
        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        // Build a list of platform events from the opportunities
        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            Deal_Stage_Change__e ev = new Deal_Stage_Change__e();
            ev.Opportunity_Id__c = opp.Id;          // 18‑character Opportunity Id
            ev.Stage__c = opp.StageName;            // Opportunity stage name
            ev.Amount__c = opp.Amount;              // Opportunity amount
            events.add(ev);
        }

        // Publish all events in one call – this counts as a single DML operation
        List<Database.SaveResult> publishResults = EventBus.publish(events);

        // The results are returned in the same order as the events list,
        // which matches the original opportunities order.
        return publishResults;
    }
}
