    // Collect AccountIds that need rating recalculation
    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.new) {
        if (opp.AccountId == null) {
            continue;
        }

        if (Trigger.isInsert) {
            // New opportunity always affects its account's rating
            accountIds.add(opp.AccountId);
        } else {
            // Update: only if StageName or Amount changed
            Opportunity old = Trigger.oldMap.get(opp.Id);
            if (old.StageName != opp.StageName || old.Amount != opp.Amount) {
                accountIds.add(opp.AccountId);
            }
        }
    }

    // If there are accounts to recalculate, invoke the async service
    if (!accountIds.isEmpty()) {
        // Batch the IDs into a single future call to stay within governor limits
        AccountRatingService.recalculate(new List<Id>(accountIds));
    }
