public class CaseSurveyJob implements Queueable {
    private List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        if (caseIds == null || caseIds.isEmpty()) return;

        // Retrieve the cases we need to process
        Map<Id, Case> casesById = new Map<Id, Case>(
            [SELECT Id, ContactId, CaseNumber
             FROM Case
             WHERE Id IN :caseIds]
        );

        // Process each case individually so a failure on one case doesn't block others
        for (Id caseId : caseIds) {
            Case c = casesById.get(caseId);
            if (c == null || c.ContactId == null) {
                // No contact or case missing – nothing to do
                continue;
            }

            try {
                Task t = new Task();
                t.WhatId = c.Id;
                t.WhoId = c.ContactId;
                t.Subject = 'CSAT survey: ' + c.CaseNumber;
                t.ActivityDate = Date.today().addDays(2);
                t.Status = 'Not Started';
                insert t;   // DML per case isolates failures
            } catch (Exception ex) {
                // Log the error; in a production org you might send an alert or write to a custom error object
                System.debug(
                    LoggingLevel.ERROR,
                    'CaseSurveyJob failed to create task for Case Id ' + caseId + ': ' + ex.getMessage()
                );
            }
        }
    }
}
