public with sharing class AccountCountrySync {
    /**
     * Handles the after‑update logic for Account.
     * When an Account's BillingCountry changes, updates the MailingCountry on its Contacts
     * where the Contact's MailingCountry is blank or matches the Account's previous BillingCountry.
     *
     * @param newAccounts   List of Account records after the update.
     * @param oldAccounts   Map of Account Ids to their state before the update.
     */
    public static void handleAfterUpdate(List<Account> newAccounts, Map<Id, Account> oldAccounts) {
        // Identify Accounts whose BillingCountry actually changed.
        Set<Id> changedAccountIds = new Set<Id>();
        Map<Id, String> newBillingCountryById = new Map<Id, String>();
        Map<Id, String> oldBillingCountryById = new Map<Id, String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldAccounts.get(acc.Id);
            if (oldAcc == null) continue; // safety guard; should not happen in after update
            if (acc.BillingCountry != oldAcc.BillingCountry) {
                changedAccountIds.add(acc.Id);
                newBillingCountryById.put(acc.Id, acc.BillingCountry);
                oldBillingCountryById.put(acc.Id, oldAcc.BillingCountry);
            }
        }

        // No changes → nothing to do.
        if (changedAccountIds.isEmpty()) return;

        // Load Contacts only for the accounts that changed (single query, no loops).
        List<Contact> contactsToCheck = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ];

        // Group Contacts by AccountId for quick lookup.
        Map<Id, List<Contact>> contactsByAccountId = new Map<Id, List<Contact>>();
        for (Contact c : contactsToCheck) {
            if (!contactsByAccountId.containsKey(c.AccountId)) {
                contactsByAccountId.put(c.AccountId, new List<Contact>());
            }
            contactsByAccountId.get(c.AccountId).add(c);
        }

        // Prepare Contacts that need updating.
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Id accId : changedAccountIds) {
            String newCountry = newBillingCountryById.get(accId);
            String oldCountry = oldBillingCountryById.get(accId);
            List<Contact> accContacts = contactsByAccountId.get(accId);
            if (accContacts == null) continue; // no contacts for this account

            for (Contact c : accContacts) {
                // Update if MailingCountry is blank or equals the old BillingCountry.
                if (c.MailingCountry == null || c.MailingCountry == oldCountry) {
                    c.MailingCountry = newCountry;
                    contactsToUpdate.add(c);
                }
            }
        }

        // Perform bulk update if needed.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
