import { LightningElement, api, wire } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';
import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ANNUALREVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

export default class AccountHeader extends LightningElement {
    @api recordId;

    @wire(getRecord, { recordId: '$recordId', fields: [
        NAME_FIELD,
        INDUSTRY_FIELD,
        ANNUALREVENUE_FIELD,
        OWNER_NAME_FIELD
    ] })
    record;

    get name() {
        if (!this.record.data) {
            return undefined;
        }
        return getFieldValue(this.record.data, NAME_FIELD);
    }

    get industry() {
        if (!this.record.data) {
            return undefined;
        }
        return getFieldValue(this.record.data, INDUSTRY_FIELD);
    }

    get revenue() {
        if (!this.record.data) {
            return undefined;
        }
        return getFieldValue(this.record.data, ANNUALREVENUE_FIELD);
    }

    get ownerName() {
        if (!this.record.data) {
            return undefined;
        }
        return getFieldValue(this.record.data, OWNER_NAME_FIELD);
    }

    get loading() {
        return !this.record.data && !this.record.error;
    }

    get errorMessage() {
        if (this.record.error) {
            return this.record.error.body?.message || this.record.error.message || 'Unknown error';
