import { LightningElement, wire, api } from 'lwc';
import getContacts from '@salesforce/apex/ContactController.getContacts';
import { updateRecord } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import { refreshApex } from '@salesforce/apex';

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts;

    columns = [
        { label: 'Name', fieldName: 'Name', type: 'text', editable: false },
        { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
        { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
        { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
    ];

    draftValues = [];

    get contacts() {
        return this.wiredContacts?.data;
    }

    handleSave(event) {
        const draftValues = event.detail.draftValues;
        // Each call to updateRecord expects { fields: {...draft} }
        const updatePromises = draftValues.map(draft =>
            updateRecord({ fields: draft })
        );

        Promise.allSettled(updatePromises)
            .then(results => {
                const errors = results.filter(r => r.status === 'rejected');
                if (errors.length === 0) {
                    this.dispatchEvent(
                        new ShowToastEvent({
                            title: 'Contacts updated',
                            variant: 'success',
                            message: 'All contacts were saved successfully.'
                        })
                    );
                    this.draftValues = []; // clear draft values
                    return refreshApex(this.wiredContacts);
                } else {
                    // Use the first error's message
                    const firstError = errors[0].reason;
                    const message = firstError.body?.message || firstError.message || 'Unknown error';
                    this.dispatchEvent(
                        new ShowToastEvent({
                            title: 'Could not save contacts',
                            variant: 'error',
                            message
                        })
                    );
                }
            })
            .catch(error => {
                // Catch any unexpected error in the promise handling
                const message = error.body?.message || error.message || 'Unexpected error';
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Could not save contacts',
                        variant: 'error',
                        message
                    })
                );
            });
    }
}
