import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label = '';
    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        this._syncStateFromProps();
    }
    @api
    get value() {
        return this._value;
    }
    set value(v) {
        this._value = v;
        this._syncStateFromProps();
    }

    // private state
    _options = [];
    _value = null;
    _activeIndex = -1;
    _uid = Math.floor(Math.random() * 10000);
    _selectedValue = null; // mirrors _value for internal use

    constructor() {
        super();
    }

    connectedCallback() {
        this._syncStateFromProps();
    }

    /** Keep internal state in sync with public props */
    _syncStateFromProps() {
        const opts = this._options;
        const val = this._value;
        // Determine if the current value matches an option
        const selectedIndex = opts.findIndex(o => o.value === val);
        this._selectedValue = val; // may be null
        // Active index: if a selected option exists, use it; otherwise first option if any
        if (selectedIndex !== -1) {
            this._activeIndex = selectedIndex;
        } else {
            this._activeIndex = opts.length > 0 ? 0 : -1;
        }
    }

    /** ID generator for each option */
    getOptionId(opt) {
        return `${opt.value}-option-${this._uid}`;
    }

    /** Computed aria-activedescendant value */
    get activeId() {
        if (this._activeIndex >= 0 && this._options[this._activeIndex]) {
            const opt = this._options[this._activeIndex];
            return `${opt.value}-option-${this._uid}`;
        }
        return undefined;
    }

    /** Select an option by its value */
    _selectOptionByValue(val) {
        const opts = this._options;
        const index = opts.findIndex(o => o.value === val);
        if (index === -1) return;
        const oldVal = this._selectedValue;
        if (oldVal === val) {
            // already selected – nothing to do
            return;
        }
        this._selectedValue = val;
        this._activeIndex = index;
        this.dispatchEvent(new CustomEvent('change', {
            detail: { value: val }
        }));
    }

    /** Keyboard handling for the listbox */
    handleKeyDown(event) {
        const key = event.key;
        const preventKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
        if (!preventKeys.includes(key)) {
            return;
        }
        event.preventDefault();

        if (!this._options || this._options.length === 0) {
            return;
        }

        let newIndex = this._activeIndex;
        switch (key) {
            case 'ArrowDown':
                if (newIndex < this._options.length - 1) newIndex++;
                break;
            case 'ArrowUp':
                if (newIndex > 0) newIndex--;
                break;
            case 'Home':
                newIndex = 0;
                break;
            case 'End':
                newIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                const activeOpt = this._options[this._activeIndex];
                if (activeOpt) {
                    this._selectOptionByValue(activeOpt.value);
                }
                return; // active remains the same after selection
            default:
                return;
        }

        // Update active index for movement keys
        if (key !== 'Enter' && key !== ' ') {
            this._activeIndex = newIndex;
        }
    }

    /** Click handler for an option */
    handleClickOption(event) {
        const li = event.currentTarget;
        const val = li.dataset.value;
        if (val !== null) {
            this._selectOptionByValue(val);
        }
    }
}
