/**
 * FamilyService
 * Utility for creating NPSP Relationship records linking parents to children.
 */
public with sharing class FamilyService {
    /**
     * Links each parent to their child as a Parent relationship (status Current).
     * Skips pairs where any relationship already exists between the two contacts
     * (in either direction) to allow safe re‑runs.
     *
     * @param parentIdByChildId Map where key = Child Contact Id, value = Parent Contact Id
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Guard clause for null or empty input
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect all child and parent Ids for the existence check
        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null) childIds.add(childId);
            if (parentId != null) parentIds.add(parentId);
        }

        // Query existing relationships that involve any of these contacts in either direction
        // Single SOQL as required
        List<npe4__Relationship__c> existingRels = [
            SELECT Id, npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (
                (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
                OR
                (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
            )
        ];

        // Build a set representing existing pairs in both directions
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : existingRels) {
            String key1 = rel.npe4__Contact__c + '|' + rel.npe4__RelatedContact__c;
            String key2 = rel.npe4__RelatedContact__c + '|' + rel.npe4__Contact__c;
            existingPairKeys.add(key1);
            existingPairKeys.add(key2);
        }

        // Prepare relationship records to insert
        List<npe4__Relationship__c> relsToInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }
            String pairKey = childId + '|' + parentId;
            String reverseKey = parentId + '|' + childId;
            // Skip if any relationship already exists between these two contacts
            if (existingPairKeys.contains(pairKey) || existingPairKeys.contains(reverseKey)) {
                continue;
            }
            npe4__Relationship__c rel = new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            );
            relsToInsert.add(rel);
        }

        // Perform a single DML if there are records to insert
        if (!relsToInsert.isEmpty()) {
            insert relsToInsert;
        }
    }
}
