public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    public override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist,
                                                      List<SObject> oldlist,
                                                      npsp.TDTM_Runnable.Action triggerAction,
                                                      Schema.DescribeSObjectResult objResult) {
        // Only handle after insert and after update
        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
            triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            // Return an empty wrapper (no DML)
            return new npsp.TDTM_Runnable.DmlWrapper(
                new List<SObject>(),
                new List<SObject>(),
                new List<SObject>(),
                new List<SObject>()
            );
        }

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity opp = (Opportunity)newlist[i];
            Boolean isQualified = opp.IsClosed &&
                                  opp.IsWon &&
                                  opp.Amount != null &&
                                  opp.Amount >= 5000;

            if (!isQualified) {
                continue;
            }

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
                // New record that meets criteria
                tasksToInsert.add(buildTask(opp));
            } else { // AfterUpdate
                Opportunity oldOpp = (oldlist != null && i < oldlist.size())
                                        ? (Opportunity)oldlist[i]
                                        : null;
                Boolean oldQualified = false;
                if (oldOpp != null) {
                    oldQualified = oldOpp.IsClosed &&
                                   oldOpp.IsWon &&
                                   oldOpp.Amount != null &&
                                   oldOpp.Amount >= 5000;
                }
                // Transition from not qualified to qualified
                if (!oldQualified) {
                    tasksToInsert.add(buildTask(opp));
                }
            }
        }

        if (tasksToInsert.isEmpty()) {
            // No tasks to create – return empty wrapper
            return new npsp.TDTM_Runnable.DmlWrapper(
                new List<SObject>(),
                new List<SObject>(),
                new List<SObject>(),
                new List<SObject>()
            );
        }

        // Return wrapper with the tasks to insert
        return new npsp.TDTM_Runnable.DmlWrapper(
            tasksToInsert,   // newList
            new List<SObject>(), // updateList
            new List<SObject>(), // deleteList
            new List<SObject>()  // undeleteList
        );
    }

    private Task buildTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = 'Major gift thank-you call';
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        t.WhoId = opp.npsp__Primary_Contact__c; // may be null
        t.OwnerId = opp.OwnerId;
        t.ActivityDate = (opp.CloseDate != null) ? opp.CloseDate.addDays(3) : Date.today().addDays(3);
        return t;
    }
}
