public class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    private static final String DUPLICATE_EMAIL_ERROR = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        process(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        process(triggerNew, triggerOld);
    }

    private void process(List<SObject> triggerNew, List<SObject> triggerOld) {
        // Determine which contacts need to be evaluated
        List<Contact> contactsToCheck = new List<Contact>();
        Map<Id, Contact> oldMap = (triggerOld != null) ? new Map<Id, Contact>(triggerOld) : null;
        Set<Id> accountIds = new Set<Id>();
        Set<String> normalizedEmails = new Set<String>();
        Set<Id> evalContactIds = new Set<Id>();

        for (SObject s : triggerNew) {
            Contact con = (Contact)s;
            // Skip if missing Account or Email
            if (con.AccountId == null || con.Email == null) continue;

            Boolean needsCheck = false;
            if (triggerOld == null) {
                needsCheck = true; // insert
            } else {
                Contact old = oldMap.get(con.Id);
                if (old == null) {
                    needsCheck = true; // safety, should not happen in update
                } else if (!con.Email.equals(old.Email) || !con.AccountId.equals(old.AccountId)) {
                    needsCheck = true; // Email or AccountId changed
                }
            }
            if (!needsCheck) continue;

            contactsToCheck.add(con);
            accountIds.add(con.AccountId);
            normalizedEmails.add(con.Email.toLowerCase());
            if (con.Id != null) evalContactIds.add(con.Id);
        }

        if (contactsToCheck.isEmpty()) return;

        // Fetch existing contacts that could conflict
        List<Contact> existingContacts = [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
        ];

        // Build set of existing keys (AccountId_EmailLower) excluding contacts being processed
        Set<String> existingKeys = new Set<String>();
        for-Contact ex : existingContacts) {
            if (evalContactIds.contains(ex.Id)) continue;
            String key = ex.AccountId + '_' + ex.Email.toLowerCase();
            existingKeys.add(key);
        }

        // Track keys seen so far (existing + earlier in this batch)
        Map<String, Boolean> seenKeys = new Map<String, Boolean>();
        for (String k : existingKeys) {
            seenKeys.put(k, true);
        }

        // Evaluate each contact in order
        for (Contact con : contactsToCheck) {
            String key = con.AccountId + '_' + con.Email.toLowerCase();
            if (seenKeys.containsKey(key)) {
                con.addError(DUPLICATE_EMAIL_ERROR);
            } else {
                seenKeys.put(key, true);
            }
        }
    }
}
